package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    unencrypted_protocols := {"http://", "ftp://", "telnet://", "ldap://"}
    attr.name in {"url", "endpoint", "uri", "connection_string", "protocol", "path"}
    attr.value.ir_type == "String"
    regex.match(sprintf("(?i)^(%s)", [concat("|", unencrypted_protocols)]), attr.value.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext Transmission of Sensitive Information - Using unencrypted protocols for sensitive data. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    encryption_flags := {"ssl_enabled", "tls_disabled", "enforce_https", "validate_certs", "ssl_mode", "require_ssl", "enable_https_traffic_only"}
    attr.name in encryption_flags
    attr.value.ir_type == "String"
    (attr.value.value == "false" || attr.value.value == "disable")

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext Transmission of Sensitive Information - Encryption explicitly disabled. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"password", "api_key", "secret", "token", "credential"}
    attr.value.ir_type == "String"
    count(attr.value.value) > 0

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext Transmission of Sensitive Information - Sensitive data in plaintext configuration. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    plaintext_ports := {"80", "21", "23", "389"}
    attr.name in {"port", "ports"}
    attr.value.ir_type == "String"
    attr.value.value in plaintext_ports

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext Transmission of Sensitive Information - Plaintext port configured. (CWE-319)"
    }
}

